import re
import pandas as pd
from datetime import date

_NUM_RE = re.compile(r'^[+-]?\d+(\.\d{1,2})?$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')

_VALID_CURRENCIES = {'USD', 'EUR', 'GBP'}


def _is_null(v):
    if v is None:
        return True
    if isinstance(v, float) and pd.isna(v):
        return True
    try:
        if pd.isna(v):
            return True
    except (TypeError, ValueError):
        pass
    return False


def _trim(v):
    return v.strip()


def _parse_date(s):
    if not _DATE_RE.match(s):
        return None
    year_s, month_s, day_s = s.split('-')
    try:
        y = int(year_s)
        m = int(month_s)
        d = int(day_s)
    except ValueError:
        return None
    if len(year_s) != 4 or len(month_s) != 2 or len(day_s) != 2:
        return None
    try:
        return date(y, m, d)
    except ValueError:
        return None


def run(inputs: dict) -> dict:
    raw = inputs["raw_payments"]

    valid_rows = []
    reject_rows = []
    survivors = []  # rows passing R1-R5, with parsed values

    for _, row in raw.iterrows():
        row_num = row["row_num"]
        payment_id = row["payment_id"]
        account_id = row["account_id"]
        amount_txt = row["amount_txt"]
        currency = row["currency"]
        pay_date_txt = row["pay_date_txt"]

        # R1 MISSING_ID
        if _is_null(payment_id) or _trim(str(payment_id)) == "":
            reject_rows.append((row_num, "MISSING_ID"))
            continue

        trimmed_id = _trim(str(payment_id))

        # R2 BAD_AMOUNT
        if _is_null(amount_txt):
            reject_rows.append((row_num, "BAD_AMOUNT"))
            continue
        amount_str = _trim(str(amount_txt))
        if not _NUM_RE.match(amount_str):
            reject_rows.append((row_num, "BAD_AMOUNT"))
            continue
        amount_val = float(amount_str)

        # R3 NON_POSITIVE
        if amount_val <= 0:
            reject_rows.append((row_num, "NON_POSITIVE"))
            continue

        # R4 BAD_CURRENCY
        if _is_null(currency):
            reject_rows.append((row_num, "BAD_CURRENCY"))
            continue
        currency_up = _trim(str(currency)).upper()
        if currency_up not in _VALID_CURRENCIES:
            reject_rows.append((row_num, "BAD_CURRENCY"))
            continue

        # R5 BAD_DATE
        if _is_null(pay_date_txt):
            reject_rows.append((row_num, "BAD_DATE"))
            continue
        date_str = _trim(str(pay_date_txt))
        parsed_date = _parse_date(date_str)
        if parsed_date is None:
            reject_rows.append((row_num, "BAD_DATE"))
            continue

        survivors.append({
            "row_num": row_num,
            "payment_id": trimmed_id,
            "account_id": account_id,
            "amount": amount_val,
            "currency": currency_up,
            "pay_date": parsed_date,
        })

    # R6 DUPLICATE: group survivors by trimmed payment_id, keep lowest row_num
    groups = {}
    for s in survivors:
        groups.setdefault(s["payment_id"], []).append(s)

    for pid, group in groups.items():
        group_sorted = sorted(group, key=lambda x: x["row_num"])
        winner = group_sorted[0]
        valid_rows.append(winner)
        for loser in group_sorted[1:]:
            reject_rows.append((loser["row_num"], "DUPLICATE"))

    valid_df = pd.DataFrame(valid_rows, columns=[
        "row_num", "payment_id", "account_id", "amount", "currency", "pay_date"
    ])
    if not valid_df.empty:
        valid_df = valid_df.sort_values("row_num").drop(columns=["row_num"]).reset_index(drop=True)
    else:
        valid_df = pd.DataFrame(columns=["payment_id", "account_id", "amount", "currency", "pay_date"])

    reject_df = pd.DataFrame(reject_rows, columns=["row_num", "reject_reason"])
    if not reject_df.empty:
        reject_df = reject_df.sort_values("row_num").reset_index(drop=True)
    else:
        reject_df = pd.DataFrame(columns=["row_num", "reject_reason"])

    return {
        "valid_payments": valid_df,
        "payment_rejects": reject_df,
    }
